/** @purpose Render todos as human-readable terminal text. */
import type { Todo } from "./types";

export function formatTodo(todo: Todo): string {
  const box = todo.completed ? "[x]" : "[ ]";
  return `${box} ${todo.title}`;
}

export function formatList(todos: Todo[]): string {
  if (todos.length === 0) return "No todos.";
  return todos.map(formatTodo).join("\n");
}

import { describe, expect, it } from "vitest";
import { formatList, formatTodo } from "./format";

describe("format", () => {
  it("formats open and done todos", () => {
    expect(formatTodo({ id: 1, title: "milk", completed: false })).toBe("[ ] milk");
    expect(formatTodo({ id: 2, title: "eggs", completed: true })).toBe("[x] eggs");
  });
  it("handles an empty list", () => expect(formatList([])).toBe("No todos."));
});

/** @purpose Execute CLI commands against the todo store and return output text. */
import { load, save } from "./storage";
import { formatList } from "./format";
import { nextId, type Command, type Todo } from "./types";

export interface ListOptions {
  includeDone?: boolean;
}

export function add(todos: Todo[], title: string, due?: string): Todo[] {
  const todo: Todo = { id: nextId(todos), title, completed: false };
  if (due) todo.due = due;
  return [...todos, todo];
}

export function complete(todos: Todo[], id: number): Todo[] {
  if (!todos.some((t) => t.id === id)) throw new Error(`No todo with id ${id}`);
  return todos.map((t) => (t.id === id ? { ...t, completed: true } : t));
}

export function list(todos: Todo[], opts: ListOptions = {}): string {
  const visible = opts.includeDone === false ? todos.filter((t) => !t.completed) : todos;
  return formatList(visible);
}

export function parseArgs(argv: string[]): Command {
  const [kind, ...rest] = argv;
  if (kind === "add") return { kind: "add", title: rest[0], due: rest[1] };
  if (kind === "complete") return { kind: "complete", id: Number(rest[0]) };
  return { kind: "list" };
}

export function run(path: string, cmd: Command): string {
  const todos = load(path);
  switch (cmd.kind) {
    case "add": {
      const next = add(todos, cmd.title, cmd.due);
      save(path, next);
      return `Added #${next[next.length - 1].id}`;
    }
    case "complete":
      save(path, complete(todos, cmd.id));
      return `Completed #${cmd.id}`;
    case "list":
      return list(todos);
  }
}

import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { add, complete, list, parseArgs, run } from "./commands";

describe("commands", () => {
  it("adds and completes", () => {
    const todos = complete(add(add([], "milk"), "eggs"), 1);
    expect(todos.map((t) => t.completed)).toEqual([true, false]);
  });
  it("lists, optionally hiding done items", () => {
    const todos = complete(add(add([], "milk"), "eggs"), 1);
    expect(list(todos)).toBe("[x] milk\n[ ] eggs");
    expect(list(todos, { includeDone: false })).toBe("[ ] eggs");
  });
  it("runs commands against a file", () => {
    const path = join(mkdtempSync(join(tmpdir(), "todo-")), "todos.json");
    expect(run(path, { kind: "add", title: "milk" })).toBe("Added #1");
    expect(run(path, { kind: "list" })).toBe("[ ] milk");
  });
});

describe("parseArgs", () => {
  it("parses each command", () => {
    expect(parseArgs(["add", "milk", "2026-11-01"])).toEqual({ kind: "add", title: "milk", due: "2026-11-01" });
    expect(parseArgs(["complete", "2"])).toEqual({ kind: "complete", id: 2 });
    expect(parseArgs(["list"])).toEqual({ kind: "list" });
  });
});

